/** Finance controls reuse the incumbent workspace form and table vocabulary. */
final class OfficeExpenseFinancialPage
{
    private bool $ar;private array $s;private string $csrf;private int $fieldNumber=0;
    private static function e($v): string {return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private function t(string $ar,string $en): string {return $this->ar?$ar:$en;}
    private function hidden(string $name,$value): string {return '<input type="hidden" name="'.self::e($name).'" value="'.self::e($value).'">';}
    private function tokens(string $action,?array $row=null): string
    {
        $h='';foreach(['token'=>$this->csrf,'action'=>$action,'office'=>$this->s['office'],'lang'=>$this->s['language'],'kind'=>$row['kind']??'settings','id'=>$row['id']??'','revision'=>$row['revision']??($this->s['finance_config']['revision']??0),'key'=>bin2hex(random_bytes(16))]as$k=>$v)$h.=$this->hidden($k,$v);return $h;
    }
    private function input(string $key,string $label,string $value='',string $type='text',bool $required=true): string
    {$id='finance-field-'.(++$this->fieldNumber);return '<label class="workspace-finance-field" for="'.$id.'">'.self::e($label).'<input id="'.$id.'" name="payload['.self::e($key).']" type="'.self::e($type).'" value="'.self::e($value).'"'.($required?' required':'').($type==='number'?' min="0" step="1"':'').'></label>';}
    private function select(string $key,string $label,array $options,$selected): string
    {
        $id='finance-field-'.(++$this->fieldNumber);$h='<label class="workspace-finance-field" for="'.$id.'">'.self::e($label).'<select id="'.$id.'" name="payload['.self::e($key).']">';foreach($options as$id=>$name)$h.='<option value="'.self::e($id).'"'.((string)$selected===(string)$id?' selected':'').'>'.self::e($name).'</option>';return $h.'</select></label>';
    }
    public function render(array $s,string $csrf): string
    {
        $this->s=$s;$this->ar=$s['language']==='ar';$this->csrf=$csrf;if(empty($s['finance'])||$s['print'])return '';
        if($s['view']==='reports'&&isset($s['financial_report']))return $this->postedReport($s['financial_report']);
        if($s['view']==='settings'&&isset($s['finance_config'],$s['finance_metadata']))return $this->setup();
        if($s['view']==='treasury'&&!$s['selected'])return $this->paymentAccounts().$this->openings();
        $r=$s['selected'];if(!$r||!in_array($r['kind'],OfficeExpenseFinancialPlan::KINDS,true))return '';$f=$s['finance'];$v=$r['content']['_finance']??[];
        $progress=OfficeExpenseRequestProgress::workspace($r,$f,$s['language']);
        $h=$progress.'<section class="workspace-card workspace-finance" id="financial-record"><h2>'.$this->t('الدفع والترحيل المالي','Payment & financial posting').'</h2>';
        if($r['kind']==='opening')$h.='<p class="workspace-notice">'.$this->t('تسوية محاسبية للرصيد الافتتاحي الموجود في Dolibarr. لا يُضاف مبلغ إلى الخزنة ولا يتكرر الإيداع. يجب مراجعة القيمة التاريخية بعملة الدفاتر.','GL representation of the existing native opening. No cash is added and the deposit is not repeated. Review its historical book-currency valuation.').'</p>';
        if(!empty($f['readiness_issue']))$h.='<p class="workspace-help" dir="ltr">'.self::e($f['readiness_issue']).'</p>';
        if(!$f['enabled'])$h.='<p class="workspace-notice">'.$this->t('الدفع متوقف حتى تفعيل المحاسبة واعتماد حسابات الفرع من الإعدادات. يمكنك تجهيز المسودة وإرفاق الإثبات الآن.','Payments are disabled until native accounting and branch mappings are approved in Settings. Prepare drafts and attach evidence now.').'</p>';
        $h.='<h3>'.$this->t('مستندات الإثبات','Supporting documents').'</h3>';
        foreach($f['evidence']as$file)$h.='<form method="post" action="finance.php" class="workspace-finance-file">'.$this->tokens('download',$r).$this->hidden('file_id',$file['id']).'<span>'.self::e($file['name']).' · '.self::e(number_format($file['size']/1024,1)).' KB</span><button class="button button-muted" type="submit">'.$this->t('تنزيل','Download').'</button></form>';
        if(!$f['evidence'])$h.='<p>'.$this->t('لا توجد مرفقات بعد.','No attachments yet.').'</p>';
        if($f['evidence_available']&&$f['submit']&&in_array($r['status'],['draft','rejected'],true))$h.='<form method="post" action="finance.php" enctype="multipart/form-data" class="workspace-finance-file">'.$this->tokens('attach',$r).'<label>'.$this->t('PDF أو صورة · بحد أقصى 5 ميجابايت','PDF or image · up to 5MB').'<input name="evidence" type="file" accept=".pdf,.png,.jpg,.jpeg" required></label><button class="button button-muted" type="submit">'.$this->t('إرفاق الإثبات','Attach evidence').'</button></form>';
        if($f['enabled']&&$f['submit']&&in_array($r['status'],['draft','rejected'],true)){
            $h.='<details open><summary>'.$this->t('تجهيز الطلب للاعتماد','Prepare for approval').'</summary><form method="post" action="finance.php">'.$this->tokens('submit',$r).'<div class="workspace-finance-grid">'.$this->input('date',$this->t('تاريخ الترحيل','Posting date'),$r['kind']==='opening'?$r['content']['date']:date('Y-m-d'),'date').$this->hidden('payload[setup_revision]',$f['revision']);
            if($r['content']['currency']!==$f['base'])$h.=$this->input('rate',$this->t('سعر الصرف: وحدة من عملة المستند إلى ','Exchange rate: one document currency unit to ').$f['base']).$this->input('rate_date',$this->t('تاريخ سعر الصرف','Exchange-rate date'),date('Y-m-d'),'date').$this->input('rate_source',$this->t('مصدر السعر المعتمد','Reviewed rate source'));
            if(in_array($r['kind'],['expense','advance','advance_return','advance_settlement'],true)){$options=[0=>$this->t('اختر الموظف','Select employee')];foreach($f['staff']as$p)$options[$p['id']]=$p['name']?:$p['login'];$h.=$this->select('staff_id',$this->t('الموظف صاحب العملية','Employee'),$options,$r['subject']>0?$r['subject']:$r['owner']);}
            if($r['kind']==='receipt'){$options=[0=>$this->t('اختر العميل الأصلي','Select native customer')];foreach($f['customers']as$p)$options[$p['rowid']]=$p['nom'];$h.=$this->select('party_id',$this->t('العميل في Dolibarr','Dolibarr customer'),$options,0);$invoices=[0=>$this->t('رصيد عميل غير مخصص لفاتورة','Unallocated customer funds')];foreach($f['invoices']??[]as$invoice)$invoices[$invoice['rowid']]=$invoice['ref'].' · '.$invoice['multicurrency_code'];$h.=$this->select('invoice_id',$this->t('الفاتورة المرتبطة','Related invoice'),$invoices,0);}
            if($r['kind']==='deposit')$h.=$this->select('funding_type',$this->t('مصدر التمويل','Funding classification'),[''=>$this->t('اختر التصنيف','Select classification'),'owner'=>$this->t('تمويل مالك','Owner funding'),'transfer'=>$this->t('تحويل · حساب وسيط للمطابقة','Transfer · clearing for reconciliation')],'');
            if($r['kind']==='payroll'&&bccomp($r['content']['loan_repayment'],'0',2)>0){$loans=[''=>$this->t('اختر السلفة المستحقة','Select outstanding advance')];foreach($f['advances']??[]as$loan)$loans[$loan['id']]=$loan['purpose'].' · '.$loan['amount'].' '.$loan['currency'];$h.=$this->select('loan_ref',$this->t('سداد سلفة الموظف','Employee advance repayment'),$loans,'');}
            if(!in_array($r['kind'],['receipt','opening'],true))$h.=$this->select('method',$this->t('طريقة الدفع','Payment method'),['cash'=>$this->t('نقدي','Cash'),'wallet'=>$this->t('محفظة','Wallet'),'transfer'=>$this->t('تحويل بنكي','Bank transfer'),'cheque'=>$this->t('شيك','Cheque')],'cash');
            $h.='</div><p>'.$this->t('إرسال للمراجعة فقط. لن يُدفع أو يُحصّل مبلغ في هذه الخطوة.','Submission only. This step makes no payment or receipt.').'</p><button class="button button-brand" type="submit">'.$this->t('إرسال للاعتماد','Submit for approval').'</button></form></details>';
        }
        if(isset($v['plan'])){
            $plan=$v['plan'];$h.='<h3>'.$this->t('معاينة القيد المعتمد','Reviewed journal preview').'</h3><p>'.self::e($plan['date'].' · '.$plan['currency'].' → '.$plan['base_currency']).'</p><div class="table-scroll" tabindex="0"><table><thead><tr><th>'.$this->t('التصنيف المحاسبي','Account role').'</th><th>'.$this->t('مدين','Debit').'</th><th>'.$this->t('دائن','Credit').'</th></tr></thead><tbody>';
            foreach($plan['journal_preview']['journals']??[['code'=>'','label'=>'','lines'=>$plan['lines']]]as$journal){if($journal['code']!=='')$h.='<tr><th colspan="3">'.self::e($journal['code'].' · '.$journal['label']).'</th></tr>';foreach($journal['lines']as$line)$h.='<tr><td>'.self::e(isset($line['account'])?$line['account'].' · '.$line['label']:self::roleLabel($line['role'],$this->ar)).'</td><td><bdi>'.self::e($line['debit']).'</bdi></td><td><bdi>'.self::e($line['credit']).'</bdi></td></tr>';}$h.='</tbody></table></div><p>'.$this->t('حركة الخزنة بالعملة الأصلية: ','Original-currency cash movement: ').'<bdi>'.self::e($plan['cash_amount'].' '.$plan['currency']).'</bdi></p>';
            if($r['status']==='submitted'&&$f['permissions']['approve'])$h.='<form method="post" action="finance.php">'.$this->tokens('approve',$r).$this->hidden('payload[confirmation]',$f['confirmation']).'<button class="button button-brand" type="submit">'.$this->t('اعتماد المبلغ والقيد','Approve amount & journal').'</button></form>';
            if($r['status']==='approved'&&$f['permissions']['post']&&$f['enabled'])$h.='<details><summary>'.$this->t('تنفيذ الدفع / التحصيل الفعلي','Execute actual payment / receipt').'</summary><form method="post" action="finance.php">'.$this->tokens('post',$r).$this->hidden('payload[confirmation]',$f['confirmation']).'<p>'.($r['kind']==='opening'?$this->t('سيُسجل القيد الافتتاحي فقط مقابل حركة الخزنة الموجودة.','Only the opening journal is created against the existing cash entry.'):$this->t('سيُسجل الآن الدفع أو التحصيل وحركة الخزنة والقيد المحاسبي معًا. راجع المبلغ والتاريخ قبل التنفيذ.','This records the actual payment or receipt, cash movement and accounting journal together. Review the amount and date before execution.')).'</p><button class="button receipt-green-button" type="submit">'.($r['kind']==='opening'?$this->t('تأكيد القيد الافتتاحي فقط','Confirm opening GL only'):$this->t('تأكيد التنفيذ والترحيل الآن','Confirm execution & post now')).'</button></form></details>';
        }
