        foreach(['posting','reversal']as$phase)if(isset($v[$phase])){$p=$v[$phase];$h.='<h3>'.$this->t($phase==='posting'?'مراجع الترحيل الفعلي':'مراجع القيد العكسي',$phase==='posting'?'Actual posting references':'Reversal references').'</h3><p>'.self::e('Bank #'.($p['bank_id']??'—').' · '.$p['posted_at']).'</p>';foreach($p['journals']as$j)$h.='<p>'.self::e($j['journal'].' · #'.$j['piece'].' · '.$j['debit'].' '.$p['plan']['base_currency']).'</p>';}
        if($r['status']==='posted'&&$f['permissions']['reverse']&&$f['enabled'])$h.='<details><summary>'.$this->t('عكس العملية','Reverse operation').'</summary><form method="post" action="finance.php">'.$this->tokens('reverse',$r).$this->input('date',$this->t('تاريخ القيد العكسي','Reversal date'),date('Y-m-d'),'date').$this->input('reason',$this->t('سبب العكس','Reversal reason')).'<p>'.($r['kind']==='opening'?$this->t('يُعكس القيد الافتتاحي فقط ويظل رصيد الخزنة الأصلي محفوظًا.','Only the opening GL is reversed; the original cash balance is retained.'):$this->t('تُحفظ العملية الأصلية ويُنشأ قيد وحركة عكسية مرتبطان بها.','The original is retained with a linked counter journal and cash movement.')).'</p><button class="button button-rose" type="submit">'.$this->t('تأكيد العكس','Confirm reversal').'</button></form></details>';
        if($progress===''&&isset($v['rejection_reason']))$h.='<p>'.self::e($v['rejection_reason']).'</p>';
        return $h.'</section>';
