    public static function roleLabel(string $role,bool $ar): string
    {
        $names=['cash'=>['الخزنة / البنك','Cash / bank'],'expense'=>['المصروفات','Expense'],'owner_funding'=>['تمويل المالك','Owner funding'],'transfer_clearing'=>['وسيط التحويلات','Transfer clearing'],'customer_funds'=>['أرصدة العملاء','Customer funds liability'],'customer_receivable'=>['ذمم العملاء','Customer receivable'],'staff_advance'=>['عهد الموظفين','Staff advances'],'salary_expense'=>['إجمالي الرواتب','Gross salary expense'],'salary_deductions'=>['استقطاعات الرواتب','Salary deductions'],'fx_gain'=>['أرباح فرق العملة','Realized FX gain'],'fx_loss'=>['خسائر فرق العملة','Realized FX loss'],'rounding'=>['فروق التقريب','Rounding'],'employee_payable'=>['مستحقات الموظفين','Employee payable'],'opening_equity'=>['مقابل الرصيد الافتتاحي','Opening equity']];return $names[$role][$ar?0:1]??$role;
    }
    private function paymentAccounts(): string
    {
        $rows=$this->s['finance']['payment_accounts']??[];if(!$rows)return '';$h='<section class="workspace-card"><h2>'.$this->t('حسابات البنك والمحافظ المرتبطة بالفرع','Branch bank & wallet accounts').'</h2><div class="table-scroll" tabindex="0"><table><thead><tr><th>'.$this->t('الحساب','Account').'</th><th>'.$this->t('العملة','Currency').'</th><th>'.$this->t('المتاح حتى اليوم','Available today').'</th><th>'.$this->t('الرصيد المسجل شاملاً الحركات اللاحقة','Recorded balance including future entries').'</th></tr></thead><tbody>';
        foreach($rows as$r)$h.='<tr><td>'.self::e($r['reference'].' · '.$r['label']).'</td><td>'.self::e($r['currency']).'</td><td><bdi>'.self::e($r['available']).'</bdi></td><td><bdi>'.self::e($r['balance']).'</bdi></td></tr>';return $h.'</tbody></table></div></section>';
    }
    private function openings(): string
    {
        $f=$this->s['finance'];if(!$f['administrator']||empty($f['openings']))return '';
        $options=[];foreach($f['openings']as$r)$options[$r['id']]=$r['amount'].' '.$r['currency'].' · '.$r['date'];
        return '<section class="workspace-card workspace-finance"><h2>'.$this->t('مطابقة الأرصدة الافتتاحية مع المحاسبة','Opening cash-to-GL reconciliation').'</h2><p>'.$this->t('توجد أرصدة افتتاحية بالخزنة لم تُمثل بعد في الأستاذ. احفظ إعدادات الحسابات أولًا مع إبقاء الدفع متوقفًا، ثم جهّز قيدًا لكل رصيد بسعره التاريخي المعتمد.','Native openings still need GL representation. Save reviewed mappings with payments disabled, then prepare each opening using its reviewed historical valuation.').'</p><form method="post" action="finance.php">'.$this->tokens('prepare_opening',['kind'=>'opening','id'=>'','revision'=>0]).$this->select('bank_id',$this->t('الرصيد الافتتاحي الموجود','Existing native opening'),$options,array_key_first($options)).'<button class="button button-brand" type="submit">'.$this->t('تجهيز قيد افتتاحي للمراجعة','Prepare opening for review').'</button></form></section>';
    }
    private function postedReport(array $report): string
    {
        $h='<section class="workspace-card"><h2>'.$this->t('الدفعات والتحصيلات المرحلة فعليًا','Actual posted payments & receipts').'</h2><p>'.$this->t('عمليات الموديول حسب تاريخ الترحيل. يظهر العكس في فترته، ولا يمحو الحركة الأصلية من الفترات السابقة. الأرصدة الافتتاحية في كشف الخزنة.','Module operations by posting date. A reversal appears in its own period and preserves the original period history. Opening balances are in the cash statement.').'</p>';
        $export='workspace.php?'.http_build_query(['view'=>'reports','lang'=>$this->s['language'],'office'=>$this->s['office'],'from'=>$report['from'],'to'=>$report['to'],'export'=>'financial_csv']);$h.='<a class="button button-muted" href="'.self::e($export).'">'.$this->t('تصدير الدفعات والقيود CSV','Export payments & journals CSV').'</a>';
        foreach($report['totals']as$currency=>$totals)$h.='<p><strong>'.self::e($currency).'</strong> · '.$this->t('داخل: ','In: ').self::e($totals['cash_in']).' · '.$this->t('خارج: ','Out: ').self::e($totals['cash_out']).' · '.$this->t('الصافي: ','Net: ').self::e($totals['net']).'</p>';
        foreach($report['totals']as$currency=>$totals){$max=bccomp($totals['cash_in'],$totals['cash_out'],2)>=0?$totals['cash_in']:$totals['cash_out'];if(bccomp($max,'0',2)<=0)continue;$title=$this->t('حركة نقدية فعلية · ','Actual cash flow · ').$currency;$h.='<div class="report-chart" data-report-chart><svg class="monthly-chart" viewBox="0 0 560 210" role="img" aria-label="'.self::e($title).'"><title>'.self::e($title).'</title>';foreach(['cash_in','cash_out']as$i=>$key){$width=(float)bcdiv(bcmul($totals[$key],'400',8),$max,4);$label=$this->t($key==='cash_in'?'داخل':'خارج',$key==='cash_in'?'Cash in':'Cash out').' · '.$totals[$key].' '.$currency;$h.='<text x="20" y="'.(55+$i*80).'" class="chart-tick">'.self::e($label).'</text><rect x="20" y="'.(65+$i*80).'" width="'.$width.'" height="28" rx="6" tabindex="0" data-chart-label="'.self::e($label).'" class="chart-bar chart-bar-'.($i===0?'deposit':'expense').'"/>';}$h.='</svg><p class="chart-tooltip" role="status" hidden></p></div>'; }
        $h.='<div class="table-scroll" tabindex="0"><table><thead><tr><th>'.$this->t('التاريخ / المرجع','Date / reference').'</th><th>'.$this->t('الحركة الأصلية','Original movement').'</th><th>'.$this->t('عملة الدفاتر','Book currency').'</th><th>'.$this->t('حركة الخزنة / قيود الأستاذ','Bank movement / ledger pieces').'</th></tr></thead><tbody>';
        foreach($report['rows']as$r){$url='workspace.php?'.http_build_query(['lang'=>$this->s['language'],'office'=>$this->s['office'],'view'=>OfficeExpenseWorkspaceDocument::SECTIONS[$r['kind']],'kind'=>$r['kind'],'edit'=>$r['id']]);$pieces=[];foreach($r['journals']as$j)$pieces[]=$j['journal'].' #'.$j['piece'];$h.='<tr><td><bdi>'.self::e($r['date']).'</bdi><br><a href="'.self::e($url).'#financial-record">'.self::e(substr($r['id'],0,12)).'</a>'.($r['phase']==='reversal'?' · '.$this->t('عكس','Reversal'):'').'</td><td><bdi>'.self::e($r['cash'].' '.$r['currency']).'</bdi></td><td><bdi>'.self::e($r['cash_base'].' '.$r['base_currency']).'</bdi></td><td>'.self::e('#'.$r['bank_id'].' · '.implode(' / ',$pieces)).'</td></tr>';}
        if(!$report['rows'])$h.='<tr><td colspan="4">'.$this->t('لا توجد عمليات مالية مرحلة في الفترة المحددة. المسودات تظهر في تقرير الطلبات أعلاه.','No posted financial operations in this period. Drafts appear in the request report above.').'</td></tr>';
        return $h.'</tbody></table></div></section>';
    }
    private function setup(): string
    {
        $m=$this->s['finance_metadata'];$row=$this->s['finance_config'];$v=$row['content'];$empty=[0=>$this->t('اختر حسابًا معتمدًا','Select a reviewed account')];$accounts=$empty;foreach($m['accounts']as$a)$accounts[$a['rowid']]=$a['account_number'].' · '.$a['label'];
        $h='<section class="workspace-card workspace-finance"><h2>'.$this->t('إعداد الدفع والمحاسبة','Payment & accounting setup').'</h2><p>'.$this->t('عملة دفاتر Dolibarr: ','Dolibarr book currency: ').self::e($m['base_currency']).'</p>';
        if(!$m['enabled'])return $h.'<p class="workspace-notice">'.$this->t('المحاسبة بالقيد المزدوج غير مفعّلة في Dolibarr. يلزم تفعيلها واختيار دليل الحسابات والفترة والدفاتر المعتمدة أولًا. تبقى المدفوعات متوقفة.','Native double-entry accounting is disabled. Enable it and configure the reviewed chart, period and journals first. Payments remain disabled.').'</p><a class="button button-muted" href="'.self::e(DOL_URL_ROOT.'/admin/modules.php').'">'.$this->t('إعداد وحدات Dolibarr','Dolibarr module setup').'</a></section>';
        $h.='<p>'.$this->t('دليل الحسابات الأصلي: ','Native chart: ').self::e($m['chart']).'</p><p>'.$this->t('الفترات المحاسبية المتاحة: ','Native accounting periods: ');foreach($m['periods']as$period)$h.=self::e($period['label'].' '.$period['date_start'].' → '.$period['date_end']).' · ';$h.='</p>';
