        foreach(['journal_id'=>[4,'دفتر الخزنة / البنك','Bank journal'],'expense_journal_id'=>[5,'دفتر المصروفات','Expense journal'],'adjustment_journal_id'=>[1,'دفتر التسويات','Adjustment journal'],'opening_journal_id'=>[9,'دفتر الأرصدة الافتتاحية','Opening journal']]as$key=>[$nature,$ar,$en]){$options=[0=>$this->t('اختر الدفتر','Select journal')];foreach($m['journals']as$j)if((int)$j['nature']===$nature)$options[$j['rowid']]=$j['code'].' · '.$j['label'];$h.=$this->select($key,$this->t($ar,$en),$options,$v[$key]);}
