        $types=[0=>$this->t('اختر نوع المصروف','Select expense type')];foreach($m['expense_types']as$t)$types[$t['id']]=$t['code'].' · '.$t['label'];$h.=$this->select('expense_type_id',$this->t('نوع المصروف الأصلي','Native expense type'),$types,$v['expense_type_id']);$payments=[0=>$this->t('اختر طريقة المقاصة غير النقدية','Select noncash offset type')];foreach($m['payment_types']as$p)if((int)$p['type']===3)$payments[$p['id']]=$p['code'].' · '.$p['libelle'];$h.=$this->select('offset_payment_id',$this->t('طريقة تسوية العهد دون حركة نقدية','Noncash advance-settlement payment type'),$payments,$v['offset_payment_id']).'</div><h3>'.$this->t('الحسابات المحاسبية','Ledger accounts').'</h3><div class="workspace-finance-grid">';
